/// <summary>
/// purahse order id    
/// </summary>
/// <param name = "_purchId">_purchId</param>
/// <returns>PurchId</returns>
[DataMember('PurchId'), BusinessEventsDataMember("@ProcurementAndSourcing:PurchaseOrderNumber")]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;
    return purchId;
}

/// <summary>
/// LegalEntity
/// </summary>
